<?php
require_once '../includes/auth.php'; require_role('admin'); require_once '../config/db.php'; require_once '../includes/academic.php';
$page_title='Student Management'; $msg=''; $err='';
function remove_student_records(mysqli $conn, string $username): void {
    foreach([
        ['tbl_hourly_attendance','student_username'],['tbl_student_assignments','username'],['tbl_leave_requests','username'],['tbl_resume','username']
    ] as [$table,$column]){ $st=$conn->prepare("DELETE FROM {$table} WHERE {$column}=?");$st->bind_param('s',$username);$st->execute(); }
    $st=$conn->prepare("DELETE FROM tbl_student WHERE username=?");$st->bind_param('s',$username);$st->execute();
}
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(isset($_POST['approve_student'])){
        $u=trim($_POST['username']??'');$batch=(int)($_POST['batch_id']??0);
        $st=$conn->prepare("SELECT course FROM tbl_batches WHERE id=? AND active=1");$st->bind_param('i',$batch);$st->execute();$b=$st->get_result()->fetch_assoc();
        if(!$u||!$b)$err='Select a valid course cohort.';else{$st=$conn->prepare("UPDATE tbl_student SET approved=1,course=?,batch_id=? WHERE username=?");$st->bind_param('sis',$b['course'],$batch,$u);$st->execute();$msg='Student approved and assigned to the selected cohort. Semester will progress automatically.';}
    }
    if(isset($_POST['change_batch'])){$u=trim($_POST['username']??'');$batch=(int)($_POST['batch_id']??0);$st=$conn->prepare("SELECT course FROM tbl_batches WHERE id=? AND active=1");$st->bind_param('i',$batch);$st->execute();$b=$st->get_result()->fetch_assoc();if($b){$st=$conn->prepare("UPDATE tbl_student SET batch_id=?,course=? WHERE username=? AND approved=1");$st->bind_param('iss',$batch,$b['course'],$u);$st->execute();$msg='Student cohort updated. Current semester is calculated automatically.';}else$err='Invalid cohort.';}
    if(isset($_POST['remove_student'])){$u=trim($_POST['username']??'');if($u){remove_student_records($conn,$u);$msg='Student and student-specific records removed.';}}
    if(isset($_POST['remove_batch_students'])){$batch=(int)($_POST['batch_id']??0);$st=$conn->prepare("SELECT username FROM tbl_student WHERE batch_id=?");$st->bind_param('i',$batch);$st->execute();$rs=$st->get_result();$users=[];while($r=$rs->fetch_assoc())$users[]=$r['username'];$conn->begin_transaction();try{foreach($users as $u)remove_student_records($conn,$u);$conn->commit();$msg=count($users).' student(s) removed from the selected cohort. The cohort and timetable remain.';}catch(Throwable $e){$conn->rollback();$err='Could not remove cohort students.';}}
}
if(isset($_GET['reject'])){$u=$_GET['reject'];$st=$conn->prepare("DELETE FROM tbl_student WHERE username=? AND approved=0");$st->bind_param('s',$u);$st->execute();header('Location: students.php');exit;}
$rows=$conn->query("SELECT s.*,b.batch_name,b.course batch_course,b.admission_year,b.duration_years FROM tbl_student s LEFT JOIN tbl_batches b ON b.id=s.batch_id ORDER BY s.approved ASC,s.name ASC");
$batches=$conn->query("SELECT b.*,COUNT(s.username) student_count FROM tbl_batches b LEFT JOIN tbl_student s ON s.batch_id=b.id AND s.approved=1 WHERE b.active=1 GROUP BY b.id ORDER BY b.course,b.admission_year,b.batch_name");$batchList=[];while($b=$batches->fetch_assoc())$batchList[]=$b;
require '../includes/header.php';
?>
<div class="glass-hero mb-4"><div><span class="eyebrow-dark">ADMINISTRATION</span><h2>Students & cohorts</h2><p>Students are assigned to a course cohort once. Their semester and year advance automatically from the cohort admission year.</p></div><div class="hero-orb"><i class="fa-solid fa-user-graduate"></i></div></div>
<?php if($msg): ?><div class="alert alert-success glass-alert"><?php echo e($msg); ?></div><?php endif; ?><?php if($err): ?><div class="alert alert-danger glass-alert"><?php echo e($err); ?></div><?php endif; ?>
<div class="row g-4 mb-4"><?php foreach($batchList as $b): $sem=batch_current_semester($b); ?><div class="col-md-6 col-xl-4"><div class="glass-card batch-admin-card"><div class="d-flex justify-content-between"><span class="badge badge-soft"><?php echo e($b['course']); ?></span><span class="small-muted">Current Sem <?php echo $sem; ?></span></div><h5><?php echo e($b['batch_name']); ?></h5><p class="small-muted mb-1">Admission <?php echo (int)$b['admission_year']; ?> · <?php echo (int)$b['duration_years']; ?> years</p><strong><?php echo (int)$b['student_count']; ?></strong><span class="small-muted"> active students</span><form method="POST" class="mt-3" onsubmit="return confirm('Remove ALL students from <?php echo e($b['batch_name']); ?>? Their attendance, submissions, leave requests and resumes will be removed. The cohort timetable remains.');"><input type="hidden" name="remove_batch_students" value="1"><input type="hidden" name="batch_id" value="<?php echo (int)$b['id']; ?>"><button class="btn btn-sm btn-outline-danger w-100"><i class="fa-solid fa-users-slash"></i> Remove All Students</button></form></div></div><?php endforeach; ?></div>
<div class="glass-card"><div class="d-flex justify-content-between align-items-center flex-wrap gap-2"><div><div class="section-kicker">STUDENT DIRECTORY</div><h5>Student accounts</h5></div><a class="btn btn-sm btn-primary" href="timetable.php"><i class="fa-solid fa-table-cells"></i> Manage Cohorts / Timetable</a></div><div class="table-responsive mt-4"><table class="table align-middle"><thead><tr><th>Student</th><th>Course</th><th>Cohort</th><th>Current Academic Level</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if($rows->num_rows===0): ?><tr><td colspan="6" class="empty">No students registered.</td></tr><?php endif; ?><?php while($s=$rows->fetch_assoc()): $sem=$s['admission_year']?semester_for_admission_year((int)$s['admission_year']):0; $dur=(int)($s['duration_years']??3); if($sem>$dur*2)$sem=$dur*2; ?><tr><td><strong><?php echo e($s['name']); ?></strong><br><span class="small-muted"><?php echo e($s['username']); ?> · <?php echo e($s['phone']); ?></span></td><td><?php echo e($s['course']); ?></td><td><?php echo e($s['batch_name']??'Not assigned'); ?></td><td><?php echo $sem?'Year '.(int)ceil($sem/2).' · Semester '.$sem:'Pending cohort'; ?></td><td><?php echo $s['approved']?'<span class="badge text-bg-success">Approved</span>':'<span class="badge text-bg-warning">Pending</span>'; ?></td><td><?php if($s['approved']): ?><div class="d-flex gap-2 flex-wrap"><form method="POST" class="d-flex gap-2"><input type="hidden" name="change_batch" value="1"><input type="hidden" name="username" value="<?php echo e($s['username']); ?>"><select name="batch_id" class="form-select form-select-sm"><?php foreach($batchList as $b): ?><option value="<?php echo $b['id']; ?>" <?php echo ((int)$s['batch_id']===(int)$b['id'])?'selected':''; ?>><?php echo e($b['course'].' · '.$b['batch_name']); ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-outline-primary">Move Cohort</button></form><form method="POST" onsubmit="return confirm('Permanently remove this student and student-specific records?');"><input type="hidden" name="remove_student" value="1"><input type="hidden" name="username" value="<?php echo e($s['username']); ?>"><button class="btn btn-sm btn-outline-danger"><i class="fa-solid fa-trash"></i> Remove</button></form></div><?php else: ?><form method="POST" class="d-flex gap-2 flex-wrap"><input type="hidden" name="approve_student" value="1"><input type="hidden" name="username" value="<?php echo e($s['username']); ?>"><select name="batch_id" class="form-select form-select-sm" required><option value="">Assign course cohort</option><?php foreach($batchList as $b): ?><option value="<?php echo $b['id']; ?>"><?php echo e($b['course'].' · '.$b['batch_name'].' · Admission '.$b['admission_year']); ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-success">Approve</button><a class="btn btn-sm btn-danger" href="?reject=<?php echo rawurlencode($s['username']); ?>" onclick="return confirm('Reject this student?');">Reject</a></form><?php endif; ?></td></tr><?php endwhile; ?></tbody></table></div></div>
<?php require '../includes/footer.php'; ?>
